// LC 78 子集：从 start 往后选，每个下标最多一次。空集在根上被收集。
// 换题：仍是“选哪些”且不可重复时，保持传入 i+1。
// 只收集长度为 k 的组合时，把 add 挪到 path.size()==k 再返回。
public static List<List<Integer>> subsets(int[] nums) {
    List<List<Integer>> ans = new ArrayList<>();
    dfsSubset(nums, 0, new ArrayList<Integer>(), ans);
    return ans;
}
public static void dfsSubset(int[] nums, int start, List<Integer> path, List<List<Integer>> ans) {
    ans.add(new ArrayList<Integer>(path));
    // 子集：每个前缀都是一个答案
    for (int i = start;
    i < nums.length;
    i++) {
        path.add(nums[i]);
        dfsSubset(nums, i + 1, path, ans);
        // i+1：后面的数不能再选到 i
        path.remove(path.size() - 1);
    }
}

// LC 46 全排列：每层从 0 扫描，用 used 保证每个下标只用一次。
// 换到 LC 47：先 Arrays.sort(nums)，在 if (used[i]) continue; 之后加
// if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1]) continue;
public static List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> ans = new ArrayList<>();
    boolean[] used = new boolean[nums.length];
    dfsPermute(nums, used, new ArrayList<Integer>(), ans);
    return ans;
}
public static void dfsPermute(int[] nums, boolean[] used, List<Integer> path, List<List<Integer>> ans) {
    if (path.size() == nums.length) {
        ans.add(new ArrayList<Integer>(path));
        return;
    }
    for (int i = 0;
    i < nums.length;
    i++) {
        if (used[i]) continue;
        used[i] = true;
        path.add(nums[i]);
        dfsPermute(nums, used, path, ans);
        path.remove(path.size() - 1);
        used[i] = false;
        // 与 used[i]=true 成对
    }
}

// LC 39 组合总和：排序后，当前数已经大于剩余值就 break。
// 同一数可再用，所以下一层起点仍是 i。
// 换到“每个下标一次”（LC 40）：调用改成 dfsComb(a, remain-a[i], i+1, path, ans)，
// 并在循环里加 if (i > start && a[i] == a[i-1]) continue;
public static List<List<Integer>> combinationSum(int[] candidates, int target) {
    int[] a = Arrays.copyOf(candidates, candidates.length);
    Arrays.sort(a);
    List<List<Integer>> ans = new ArrayList<>();
    dfsComb(a, target, 0, new ArrayList<Integer>(), ans);
    return ans;
}
public static void dfsComb(int[] a, int remain, int start, List<Integer> path, List<List<Integer>> ans) {
    if (remain == 0) {
        ans.add(new ArrayList<Integer>(path));
        return;
    }
    for (int i = start;
    i < a.length;
    i++) {
        if (a[i] > remain) break;
        // 升序，后面只会更大
        path.add(a[i]);
        dfsComb(a, remain - a[i], i, path, ans);
        path.remove(path.size() - 1);
    }
}

// LC 22 括号生成：任意前缀中 ')' 不超过 '('，且最终两者都等于 n。
// 换题时改两处：追加的字符，以及“还能不能追加”的条件。
// 长度仍是做完 2n 步再收集。
public static List<String> generateParenthesis(int n) {
    List<String> ans = new ArrayList<>();
    dfsParen(n, 0, 0, new StringBuilder(), ans);
    return ans;
}
public static void dfsParen(int n, int open, int close, StringBuilder path, List<String> ans) {
    if (path.length() == 2 * n) {
        ans.add(path.toString());
        return;
    }
    if (open < n) {
        path.append('(');
        dfsParen(n, open + 1, close, path, ans);
        path.deleteCharAt(path.length() - 1);
    }
    if (close < open) {
        path.append(')');
        dfsParen(n, open, close + 1, path, ans);
        path.deleteCharAt(path.length() - 1);
    }
}

