class Solution {
    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        Arrays.sort(candidates);
        // 排序后可以在 candidate > remain 时直接剪枝。
        List<List<Integer>> answer = new ArrayList<>();
        backtrack(candidates, 0, target, new ArrayList<>(), answer);
        return answer;
    }
    private void backtrack(int[] candidates, int start, int remain,
    List<Integer> path, List<List<Integer>> answer) {
        if (remain == 0) {
            answer.add(new ArrayList<>(path));
            // 当前路径的和刚好用完 target
            return;
        }
        for (int i = start;
        i < candidates.length;
        i++) {
            int value = candidates[i];
            if (value > remain) break;
            // 后面的数更大，也不可能再选。
            path.add(value);
            // 仍然传 i 而不是 i + 1，表示同一个候选数可以重复使用。
            backtrack(candidates, i, remain - value, path, answer);
            path.remove(path.size() - 1);
            // 撤销 value，改选同层下一个候选
        }
    }
}

import java.util.*;
class Solution {
    public List<List<Integer>> combinationSum2(int[] candidates, int target) {
        Arrays.sort(candidates);
        // 相同值挨在一起，后面才能按层去重并提前结束。
        List<List<Integer>> answer = new ArrayList<>();
        backtrack(candidates, 0, target, new ArrayList<>(), answer);
        return answer;
    }
    private void backtrack(int[] candidates, int start, int remain,
    List<Integer> path, List<List<Integer>> answer) {
        if (remain == 0) {
            answer.add(new ArrayList<>(path));
            return;
        }
        for (int i = start;
        i < candidates.length;
        i++) {
            // 同一层只取一次相同值，避免不同的同值下标产生相同组合。
            if (i > start && candidates[i] == candidates[i - 1]) {
                continue;
            }
            int value = candidates[i];
            if (value > remain) {
                break;
                // 已排序，后面的数都更大，不可能再凑出 remain。
            }
            path.add(value);
            // 下一层从 i+1 开始，当前这个下标不能再选。
            backtrack(candidates, i + 1, remain - value, path, answer);
            path.remove(path.size() - 1);
        }
    }
}

